import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace } from "@tigrisdata/agent-kit";
import { put } from "@tigrisdata/storage";

async function main() {
  try {
    const trialId = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
    const workspaceName = `harbor-ws-${trialId}`;

    const { data: workspace, error: wsError } = await createWorkspace(workspaceName, {
      ttl: { days: 1 },
      credentials: { role: "Editor" },
    });

    if (wsError || !workspace || !workspace.credentials) {
      console.error("Failed to create workspace:", wsError);
      process.exit(1);
    }

    const { bucket, credentials } = workspace;
    const { accessKeyId, secretAccessKey } = credentials;

    const body = JSON.stringify({ status: "ok", run: trialId });

    const { error: putError } = await put("state.json", body, {
      contentType: "application/json",
      config: {
        bucket,
        accessKeyId,
        secretAccessKey,
      },
    });

    if (putError) {
      console.error("Failed to upload state.json:", putError);
      process.exit(1);
    }

    console.log(accessKeyId);
    await writeFile("/home/user/tigris-task/output.log", accessKeyId);
  } catch (error) {
    console.error("Unexpected error:", error);
    process.exit(1);
  }
}

main();

